function lengthOfLongestSubstring(s) {
  let max = 0, start = 0, map = {};
  for (let i = 0; i < s.length; i++) {
    if (map[s[i]] >= start) start = map[s[i]] + 1;
    map[s[i]] = i;
    max = Math.max(max, i - start + 1);
  }
  return max;
}
